const headlines=[{text:"Jallianwala Bagh Massacre Shocks the Nation",date:1919,category:"Freedom Movement"},{text:"Mahatma Gandhi Launches Quit India Movement",date:1942,category:"Freedom Movement"},{text:"India Achieves Independence from British Rule",date:1947,category:"Historical Event"},{text:"India Adopts Its Constitution",date:1950,category:"Historical Event"},{text:"India Wins First Cricket World Cup",date:1983,category:"Sports Milestone"},{text:"Aryabhata: India's First Satellite Launched",date:1975,category:"Scientific Achievement"},{text:"India Conducts First Nuclear Test (Smiling Buddha)",date:1974,category:"Scientific Achievement"},{text:"Rakesh Sharma Becomes First Indian in Space",date:1984,category:"Scientific Achievement"},{text:"India Wins T20 Cricket World Cup",date:2007,category:"Sports Milestone"},{text:"Chandrayaan-3 Lands Near Moon's South Pole",date:2023,category:"Scientific Achievement"}];let currentOrder=[],score=0,draggedIndex=null,hasScored=!1;const timelineEl=document.getElementById("timeline"),shuffleBtn=document.getElementById("shuffleBtn"),checkBtn=document.getElementById("checkBtn"),scoreDisplay=document.getElementById("scoreDisplay"),resultMessage=document.getElementById("resultMessage");function shuffleArray(e){const t=[...e];for(let e=t.length-1;e>0;e--){const r=Math.floor(Math.random()*(e+1));[t[e],t[r]]=[t[r],t[e]]}return t}function renderTimeline(){timelineEl.innerHTML="",currentOrder.forEach((e,t)=>{const r=document.createElement("div");r.className="headline-card",r.draggable=!0,r.dataset.index=t,r.dataset.category=e.category,r.innerHTML=`\n      <div class="headline-text">${e.text}</div>\n      <span class="headline-category">${e.category}</span>\n    `,r.addEventListener("dragstart",handleDragStart),r.addEventListener("dragover",handleDragOver),r.addEventListener("drop",handleDrop),r.addEventListener("dragend",handleDragEnd),timelineEl.appendChild(r)})}function handleDragStart(e){draggedIndex=Number(e.currentTarget.dataset.index),e.currentTarget.classList.add("dragging")}function handleDragOver(e){e.preventDefault()}function handleDrop(e){e.preventDefault();const t=Number(e.currentTarget.dataset.index);if(null===draggedIndex||draggedIndex===t)return;const r=currentOrder[draggedIndex];currentOrder.splice(draggedIndex,1);const n=draggedIndex<t?t-1:t;currentOrder.splice(n,0,r),hasScored=!1,renderTimeline()}function handleDragEnd(e){e.currentTarget.classList.remove("dragging")}function checkOrder(){const e=document.querySelectorAll(".headline-card"),t=[...currentOrder].sort((e,t)=>e.date-t.date);let r=0;currentOrder.forEach((n,a)=>{n.date===t[a].date?(e[a].classList.add("correct"),e[a].classList.remove("wrong"),r++):(e[a].classList.add("wrong"),e[a].classList.remove("correct"))}),r===currentOrder.length?(hasScored||(score+=10,hasScored=!0),resultMessage.textContent="🎉 Perfect! All headlines are in correct chronological order!",resultMessage.className="result-message success"):(resultMessage.textContent=`Not quite right — ${r}/${currentOrder.length} correctly placed. Try again!`,resultMessage.className="result-message fail"),scoreDisplay.textContent=`Score: ${score}`}shuffleBtn.addEventListener("click",()=>{currentOrder=shuffleArray(headlines),hasScored=!1,resultMessage.textContent="",resultMessage.className="result-message",renderTimeline()}),checkBtn.addEventListener("click",checkOrder),currentOrder=shuffleArray(headlines),renderTimeline();